const sidebarGroupsOpen = {};
function sidebarLinks(items) {
  return items.map(n => `<a href="#${n[0]}" class="nav-link ${view === n[0] ? 'active' : ''}" ${view === n[0] ? 'aria-current="page"' : ''} onclick="event.preventDefault();nav('${n[0]}')">${ic(n[2])}<span>${n[1]}</span>${n[0] === 'orders' ? `<span class="nav-pill">${data.orders?.filter(o => o.status === 'Yeni').length || 0}</span>` : ''}</a>`).join('');
}
function sidebarMenu() {
  return navGroups.map((group, index) => {
    if (index === 0) return `<div class="section-label">${group[0]}</div>${sidebarLinks(group[1])}`;
    const active = group[1].some(item => item[0] === view);
    const open = sidebarGroupsOpen[index] ?? active;
    return `<details class="nav-group ${active ? 'has-active' : ''}" ${open ? 'open' : ''} ontoggle="sidebarGroupsOpen[${index}]=this.open"><summary class="nav-group-toggle"><span>${group[0]}</span>${ic('chevron',16)}</summary><div class="nav-group-items">${sidebarLinks(group[1])}</div></details>`;
  }).join('');
}
