function orderTable(arr,editable=true){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Sipariş</th><th>Müşteri</th><th>Platform</th><th>Tutar</th><th>Durum</th>${editable?'<th>İşlem</th>':''}</tr></thead><tbody>${arr.map(o=>`<tr><td><strong style="color:#28404c">#${esc(o.id)}</strong><small style="display:block;color:#a0adb4;margin-top:6px">${dt(o.date)}</small></td><td>${esc(o.customer)}</td><td><div class="flex">${logo(o.channel)}<span>${esc(o.channel)}</span></div></td><td style="font-weight:800;color:#314754">${fmt(o.total)}</td><td>${tag(o.status)}</td>${editable?`<td>${btn('Durum değiştir','openOrder('+JSON.stringify(o.id)+')','btn-small')}</td>`:''}</tr>`).join('')}</tbody></table>${arr.length?'':'<div class="empty">Eşleşen sipariş bulunamadı.</div>'}</div>`}
function productTable(arr){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Ürün</th><th>SKU</th><th>Satış Kanalları</th><th>Birim Fiyat</th><th>Stok</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${arr.map(p=>`<tr><td><div class="product-cell"><span class="product-thumb">${esc(p.image)}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small></span></div></td><td>${esc(p.sku)}</td><td>${tinylogos(p.channels)}</td><td style="font-weight:800;color:#314754">${fmt(p.price)}</td><td><strong style="color:${p.stock<=data.settings.lowStockThreshold?'#ed9952':'#3c5360'}">${p.stock} adet</strong></td><td>${tag(p.status)}</td><td>${btn('Düzenle','openEdit('+JSON.stringify(p.id)+')','btn-small')}</td></tr>`).join('')}</tbody></table>${arr.length?'':'<div class="empty">Aramanızla eşleşen ürün bulunamadı.</div>'}</div>`}
function listing(type){const isProduct=type==='products',items=data[type].filter(x=>(!filter||JSON.stringify(x).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr')))&& (statusFilter==='all'||(isProduct?x.status:x.status)===statusFilter));const chunk=items.slice((page-1)*10,page*10);let actions=isProduct?`${btn(ic('download',15)+' CSV İndir','window.location.href="/api/export/products.csv"')}${btn(ic('plus',15)+' Yeni Ürün','openProduct()','btn-primary')}`:btn(ic('download',15)+' CSV İndir','exportOrders()');return head(isProduct?'Ürün Yönetimi':'Sipariş Yönetimi',isProduct?'Ürün kataloğunuzu, stoklarınızı ve satış kanallarınızı yönetin.':'Tüm satış kanallarından gelen siparişleri tek panelde takip edin.',actions)+`<div class="card table-card"><div class="toolbar"><div class="toolbar-group"><div class="filter-search">${ic('search',15)}<input id="list-filter" value="${esc(filter)}" placeholder="${isProduct?'Ürün veya SKU ara...':'Sipariş veya müşteri ara...'}" oninput="setFilter(this.value)"/></div><select class="select" onchange="statusFilter=this.value;page=1;drawListing()"><option value="all">Tüm Durumlar</option>${(isProduct?['Aktif','Pasif']:['Yeni','Hazırlanıyor','Kargolandı','Tamamlandı','İptal']).map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><span class="muted" style="font-size:11px">${items.length} kayıt</span></div><div id="list-content">${isProduct?productTable(chunk):orderTable(chunk)}</div><div class="table-footer"><span>${items.length} kayıttan ${items.length?((page-1)*10+1):0}-${Math.min(page*10,items.length)} arası</span><div class="pagination">${Array.from({length:Math.max(1,Math.ceil(items.length/10))},(_,i)=>`<button class="pager ${i+1===page?'active':''}" onclick="page=${i+1};drawListing()">${i+1}</button>`).join('')}</div></div></div>`}
function setFilter(s){filter=s;page=1;drawListing()}function drawListing(){const isProduct=view==='products',items=data[view].filter(x=>(!filter||JSON.stringify(x).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr')))&&(statusFilter==='all'||x.status===statusFilter));$('#list-content').innerHTML=isProduct?productTable(items.slice((page-1)*10,page*10)):orderTable(items.slice((page-1)*10,page*10));$('.table-footer').innerHTML=`<span>${items.length} kayıttan ${items.length?((page-1)*10+1):0}-${Math.min(page*10,items.length)} arası</span><div class="pagination">${Array.from({length:Math.max(1,Math.ceil(items.length/10))},(_,i)=>`<button class="pager ${i+1===page?'active':''}" onclick="page=${i+1};drawListing()">${i+1}</button>`).join('')}</div>`}
function legacyConnections(){return head('Yerel demo kanalları','Mevcut örnek kayıtların kanal tercihleri.')+`<div class="promo"><div><strong>Birden fazla satış kanalı, tek bir yönetim merkezi.</strong><p>Bu bölüm eski demo kayıtlarının kanal tercihlerini yönetir. Gerçek API testleri için üstteki entegrasyon panelini kullanın.</p></div>${ic('plug',35)}</div><div class="connection-grid">${data.connections.map(c=>`<section class="card connection-card"><div><div class="connection-head"><span class="channel-logo" style="height:48px;width:48px;font-size:21px;background:${c.color}">${esc(c.initial)}</span><div><div class="connection-name">${esc(c.name)}</div><div class="connection-note">${esc(c.note)}</div></div></div></div><div class="connection-foot"><span class="dot-status ${c.enabled?'on':''}">${c.enabled?'Demo etkin':'Etkin değil'}</span>${btn(c.available?(c.enabled?'Devre dışı bırak':'Etkinleştir'):'Yakında',c.available?`toggleConnection('${c.id}',${!c.enabled})`:'notice("Bu platform için adaptör henüz yok.")','btn-small')}</div></section>`).join('')}</div>`}
function inventory(){const low=data.products.filter(p=>p.stock<=data.settings.lowStockThreshold);return head('Stok Yönetimi','Merkezi envanterinizi izleyin ve kritik stokları yönetin.',btn(ic('sync',15)+' Demo Eşitle','doSync()','btn-primary'))+`<div class="insight-grid"><div class="card insight"><span>Toplam Stok Adedi</span><b>${data.products.reduce((a,p)=>a+p.stock,0)}</b><span>Tüm ürünlerin toplamı</span></div><div class="card insight"><span>Kritik Stoklu Ürünler</span><b style="color:#e79a4c">${low.length}</b><span>Eşik: ${data.settings.lowStockThreshold} adet</span></div><div class="card insight"><span>Stok Değeri (satış fiyatı)</span><b>${fmt(data.products.reduce((a,p)=>a+p.stock*p.price,0))}</b><span>Örnek hesaplama</span></div></div><section class="card table-card"><div class="panel-head"><div><div class="panel-title">Envanter Listesi</div><div class="panel-sub">Stok düzenleme için ürün satırını kullanın</div></div>${btn('Ürünlere git '+ic('arrow',14),'nav("products")','btn-small')}</div>${productTable([...data.products].sort((a,b)=>a.stock-b.stock))}</section>`}
const originalInventory=inventory;
inventory=function(){return originalInventory().replace('Demo Eşitle','Demo Eşitle')+`<div style="margin:20px 0">${btn(ic('plus',15)+' Stok girişi / çıkışı','openStockMovement()','btn-primary')}</div><section class="card table-card"><div class="panel-head"><div class="panel-title">Stok Hareket Geçmişi</div></div><div style="overflow:auto"><table class="table"><thead><tr><th>Tarih</th><th>Ürün</th><th>Değişim</th><th>Kalan</th><th>Neden</th></tr></thead><tbody>${data.movements.slice(0,50).map(m=>`<tr><td>${dt(m.at)}</td><td>${esc(m.productName)}</td><td>${m.delta>0?'+':''}${m.delta}</td><td>${m.balance}</td><td>${esc(m.reason)}</td></tr>`).join('')||'<tr><td colspan="5">Henüz hareket bulunmuyor.</td></tr>'}</tbody></table></div></section>`};
function activityItems(arr){return `<div class="activity-list">${arr.map(a=>`<div class="activity-line"><span class="activity-icon">${ic('check',17)}</span><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></div><span class="activity-time">${ago(a.at)}</span></div>`).join('')}</div>`}function activities(){return head('İşlem Kayıtları','Ürün, bağlantı ve siparişlerde yapılan demo işlemlerini inceleyin.')+`<section class="card panel"><div class="panel-title">Son Aktiviteler</div>${activityItems(data.activity)}</section>`}
function reports(){const d=data.overview;let max=Math.max(...d.channels.map(x=>x.total),1);return head('Raporlar ve Analizler','Kanallara göre satış ve sipariş performansının örnek analizi.')+`<div class="insight-grid"><div class="card insight"><span>Toplam Ciro (Örnek)</span><b>${fmt(d.revenue)}</b><span>İptal hariç</span></div><div class="card insight"><span>Ortalama Sepet</span><b>${fmt(d.revenue/(data.orders.filter(o=>o.status!=='İptal').length||1))}</b><span>Sipariş başına</span></div><div class="card insight"><span>Bağlı Demo Kanal</span><b>${d.activeConnections}</b><span>Gerçek API bağlantısı: 0</span></div></div><div class="dashboard-grid"><section class="card panel"><div class="panel-title">Kanala Göre Satış Dağılımı</div><div class="panel-sub">Yerel demo siparişleri üzerinden</div><div class="bar-chart">${d.channels.map(c=>`<div class="bar-set"><div style="height:${Math.max(8,Math.round(c.total/max*100))}%;background:${channelColors[c.name]||'#1a8'}"></div><small>${esc(c.name)}</small></div>`).join('')}</div></section><section class="card panel"><div class="panel-title">Platform Bazlı Detay</div><div class="channels-list">${d.channels.map(c=>`<div class="channel-row">${logo(c.name)}<div class="channel-label"><span>${esc(c.name)}</span></div><span class="channel-money">${fmt(c.total)}</span></div>`).join('')}</div></section></div>`}
function syncPage(){return head('Senkronizasyon Merkezi','Veri akışları, işlem günlükleri ve entegrasyon işlerini takip edin.',btn(ic('sync',15)+' Demo Eşitle','doSync()','btn-primary'))+`<div class="promo"><div><strong>Gerçek API senkronizasyonu henüz uygulanmadı.</strong><p>Demo Eşitle yalnızca yerel bir aktivite kaydı oluşturur. Sonraki aşamada kuyruklar, retry, webhook ve platform API adaptörleri eklenecek.</p></div>${ic('sync',32)}</div><div class="settings-layout"><section class="card panel"><div class="panel-title">Sistem Durumu</div>${[['Backend API','Çalışıyor'],['Yerel Veri Deposu','Aktif'],['Gerçek Pazaryeri Bağlantıları','Bağlı değil'],['Son Demo Eşitleme',ago(data.overview.lastSync)]].map(x=>`<div class="status-stat"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</section><section class="card panel"><div class="panel-title">Son İşler</div>${activityItems(data.activity.slice(0,6))}</section></div>`}
function settings(){let s=data.settings;return head('Genel Ayarlar','Çalışma alanınızın yerel demo tercihlerini yönetin.')+`<form onsubmit="saveSettings(event)" class="settings-layout"><section class="card panel"><div class="panel-title" style="margin-bottom:22px">İşletme Bilgileri</div><div class="form-row"><label>İşletme adı</label><input name="businessName" required value="${esc(s.businessName)}"/></div><div class="form-row"><label>Para birimi</label><select name="currency"><option value="TRY" ${s.currency==='TRY'?'selected':''}>Türk Lirası (TRY)</option><option value="USD" ${s.currency==='USD'?'selected':''}>Amerikan Doları (USD)</option><option value="EUR" ${s.currency==='EUR'?'selected':''}>Euro (EUR)</option></select></div><div class="form-row"><label>Kritik stok uyarı eşiği</label><input name="lowStockThreshold" type="number" min="0" max="100000" required value="${s.lowStockThreshold}"/></div></section><section class="card panel"><div class="panel-title" style="margin-bottom:18px">Bildirim Tercihleri</div><div class="switch-line">E-posta bildirimleri (görsel tercih)<input class="switch" name="emailNotifications" type="checkbox" ${s.emailNotifications?'checked':''}/></div><div class="switch-line">Senkronizasyon bildirimleri (görsel tercih)<input class="switch" name="syncNotifications" type="checkbox" ${s.syncNotifications?'checked':''}/></div><p class="page-sub" style="line-height:1.8">Bu sürüm e-posta göndermez. Tercihler yalnızca yerel olarak kaydedilir.</p><button type="submit" class="btn btn-primary" style="margin-top:25px">${ic('check',15)} Ayarları Kaydet</button></section></form>`}
const placeholders={mapping:['Ürün Eşleştirme','Aynı ürünleri farklı platformlarda merkezi bir kimlikle yönetin.',['SKU ve barkod tabanlı eşleştirme','Varyant ve ilan kimliği yönetimi','Eşleşmeyen ürünleri tespit etme']],pricing:['Fiyat Yönetimi','Platform özelinde fiyat ve maliyet kurallarını planlayın.',['Komisyon ve kâr marjı hesaplama','Toplu fiyat güncelleme','Fiyat değişiklik geçmişi']],shipping:['Kargo İşlemleri','Gönderileri, barkodları ve takip numaralarını yönetin.',['Kargo etiketi oluşturma','Takip numarası senkronizasyonu','Toplu paket hazırlama']],returns:['İade ve İptaller','İptal ve iadeleri tek noktadan kontrol edin.',['İade talebi kayıtları','İadeden sonra stok güncelleme','Pazaryerine durum bildirimi']],invoices:['Faturalar','E-fatura ve e-Arşiv süreçlerine hazır bir alan.',['Fatura hizmet sağlayıcısı bağlantıları','Sipariş-fatura eşleştirme','Fatura PDF ve arşiv yönetimi']]};function placeholder(){const x=placeholders[view];return head(x[0],x[1])+`<section class="card placeholder-view"><div class="placeholder-icon">${ic(view==='shipping'?'truck':view==='invoices'?'file':view==='pricing'?'wallet':'layers',26)}</div><div class="eyebrow">GELECEK GELİŞTİRME AŞAMASI</div><h3>${x[0]} modülü için alan hazır</h3><p>Bu ekranın tasarımı oluşturuldu. Veri modeli ve gerçek iş akışları sonraki geliştirme aşamalarında tamamlanacak.</p><ul>${x[2].map(s=>`<li>${ic('check',15)} ${s}</li>`).join('')}</ul>${btn('Genel bakışa dön '+ic('arrow',14),'nav("dashboard")','btn-primary')}</section>`}

function barcodes(){return head('Barkod Yönetimi','Ürün barkodlarını kaydedin; kodlar bu aşamada yalnızca dahili tanımlayıcıdır.')+`<section class="card table-card"><div class="panel-head"><div class="panel-title">Ürün Barkod Kayıtları</div><div class="panel-sub">Resmî EAN/GTIN tahsis hizmeti değildir</div></div><div style="overflow:auto"><table class="table"><thead><tr><th>Ürün</th><th>SKU</th><th>Barkod</th><th>İşlem</th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td><strong>${esc(p.barcode||'Henüz yok')}</strong></td><td>${btn('Düzenle',`openBarcode('${p.id}')`,'btn-small')}</td></tr>`).join('')}</tbody></table></div></section>`}
function openBarcode(id){let p=data.products.find(x=>x.id===id);if(!p)return;showModal(`<div class="modal-head"><h3>Barkod Düzenle</h3><button class="modal-close" onclick="closeModal()">×</button></div><p>${esc(p.name)}</p><form onsubmit="saveBarcode(event,'${p.id}')"><div class="form-row"><label>Barkod / dahili kod</label><input name="barcode" maxlength="40" value="${esc(p.barcode||'')}" placeholder="Örn. 8690000000000" /></div><p class="page-sub">Geçerli GTIN/EAN tahsisi ve sağlayıcı doğrulaması bu sürümde yoktur.</p><div class="modal-foot"><button class="btn btn-primary">Kaydet</button></div></form>`)}
async function saveBarcode(e,id){e.preventDefault();let code=e.target.elements.barcode.value;await mutate(()=>api(`products/${id}/barcode`,{method:'PUT',body:JSON.stringify({barcode:code})}),'Barkod kaydedildi.')}
function shipping(){return head('Kargo Yönetimi','Siparişe gönderi kaydı ve takip numarası ekleyin.',btn(ic('plus',15)+' Yeni Gönderi','openShipment()','btn-primary'))+`<div class="promo"><div><strong>Yerel gönderi kayıtları</strong><p>Gerçek kargo firmasında gönderi veya etiket oluşturulmaz. API bağlantıları daha sonra eklenecek.</p></div>${ic('truck',30)}</div><section class="card table-card"><div class="panel-head"><div class="panel-title">Gönderiler (${data.shipments.length})</div></div><div style="overflow:auto"><table class="table"><thead><tr><th>Sipariş</th><th>Firma</th><th>Takip numarası</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${data.shipments.map(s=>`<tr><td>${esc(s.orderId)}</td><td>${esc(s.carrier)}</td><td>${esc(s.trackingNumber)}</td><td>${tag(s.status)}</td><td>${btn('Durum',`openShipmentStatus('${s.id}')`,'btn-small')}</td></tr>`).join('')||'<tr><td colspan="5">Henüz gönderi kaydı yok. Yeni gönderi oluşturun.</td></tr>'}</tbody></table></div></section>`}
function openShipment(){showModal(`<div class="modal-head"><h3>Yeni Gönderi</h3><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveShipment(event)"><div class="form-row"><label>Sipariş</label><select name="orderId" required>${data.orders.filter(o=>!data.shipments.some(s=>s.orderId===o.id)).map(o=>`<option value="${esc(o.id)}">${esc(o.id)} · ${esc(o.channel)}</option>`).join('')}</select></div><div class="form-row"><label>Kargo firması</label><select name="carrier"><option>Yurtiçi Kargo</option><option>Aras Kargo</option><option>Sürat Kargo</option><option>PTT Kargo</option><option>Diğer</option></select></div><div class="form-row"><label>Takip / gönderi numarası</label><input name="trackingNumber" required maxlength="100" placeholder="Manuel takip numarası" /></div><div class="modal-foot"><button class="btn btn-primary">Gönderiyi Kaydet</button></div></form>`)}
async function saveShipment(e){e.preventDefault();let obj=Object.fromEntries(new FormData(e.target));await mutate(()=>api('shipments',{method:'POST',body:JSON.stringify(obj)}),'Gönderi kaydedildi.')}
function openShipmentStatus(id){let s=data.shipments.find(x=>x.id===id);if(!s)return;showModal(`<div class="modal-head"><h3>Gönderi Durumu</h3><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveShipmentStatus(event,'${id}')"><div class="form-row"><label>Durum</label><select name="status">${['Hazırlanıyor','Kargoya verildi','Teslim edildi','İptal'].map(x=>`<option ${x===s.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="modal-foot"><button class="btn btn-primary">Güncelle</button></div></form>`)}
async function saveShipmentStatus(e,id){e.preventDefault();let status=e.target.elements.status.value;await mutate(()=>api(`shipments/${id}/status`,{method:'PUT',body:JSON.stringify({status})}),'Gönderi durumu kaydedildi.')}
function openStockMovement(){showModal(`<div class="modal-head"><h3>Stok Hareketi</h3><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="saveStockMovement(event)"><div class="form-row"><label>Ürün</label><select name="productId">${data.products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} (${p.stock} adet)</option>`).join('')}</select></div><div class="form-row"><label>Stok değişimi (örn. +10 veya -2)</label><input name="delta" type="number" required min="-100000" max="100000" value="1" /></div><div class="form-row"><label>Neden</label><input name="reason" required maxlength="160" placeholder="Sayım farkı, mal kabul, fire..." /></div><div class="modal-foot"><button class="btn btn-primary">Kaydet</button></div></form>`)}
async function saveStockMovement(e){e.preventDefault();let obj=Object.fromEntries(new FormData(e.target));obj.delta=Number(obj.delta);await mutate(()=>api('stock/movements',{method:'POST',body:JSON.stringify(obj)}),'Stok hareketi işlendi.')}


