function mpRead(){try{return JSON.parse(localStorage.getItem('marketpilot_v4_front_drafts')||'{}')}catch{return {}}}
let mpDrafts=mpRead();
function mpSave(){try{localStorage.setItem('marketpilot_v4_front_drafts',JSON.stringify(mpDrafts))}catch{notice('Tarayıcı kayıt alanı dolu.')}}
function mpFields(){return MP_FIELDS[view]||['Kayıt başlığı|text','Satış kanalı|channel','Referans no|text','İşlem tarihi|date','Durum|select:Taslak,İnceleniyor,Tamamlandı','Açıklama|textarea']}
function mpField(v,i,value=''){const [label,raw='text']=v.split('|'), [kind,...vals]=raw.split(':');let name='field_'+i,id='mp_'+i,opts=kind==='channel'?MP_CHANNELS:vals.join(':').split(',');let input=kind==='select'||kind==='channel'?`<select id="${id}" name="${name}">${opts.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea id="${id}" name="${name}" rows="3" placeholder="${esc(label)}">${esc(value)}</textarea>`:`<input id="${id}" name="${name}" type="${kind==='sku'?'text':kind}" ${kind==='number'?'min="0" step="0.01"':''} value="${esc(value)}" placeholder="${esc(label)}"/>`;return `<label class="mp-field"><span>${esc(label)}</span>${input}</label>`}
function mpRecords(){return mpDrafts[view]||[]}
function mpForm(i=-1){let rec=i>=0?mpRecords()[i]:null,fields=mpFields();showModal(`<div class="modal-head"><div><span class="mp-kicker">${esc(names[view])} · Örnek form</span><h3>${rec?'Taslağı düzenle':'Yeni işlem taslağı'}</h3></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="mp-modal-note">Bu form sadece tarayıcındaki örnek taslağı saklar. Gerçek pazaryeri, kargo veya fatura işlemi gerçekleştirmez.</div><form onsubmit="mpSubmit(event,${i})"><div class="mp-form-grid">${fields.map((f,j)=>mpField(f,j,rec?.values?.[j]||'')).join('')}</div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Vazgeç</button><button class="btn btn-primary" type="submit">${ic('check',15)} Taslağı kaydet</button></div></form>`)}
function mpSubmit(e,i){e.preventDefault();const values=mpFields().map((_,j)=>new FormData(e.target).get('field_'+j)||'');if(!values.some(v=>v.trim())){notice('En az bir alan doldurun.');return}let list=mpRecords(),rec={values,created:new Date().toISOString(),tab:workspaceTab[view]||operationalPages[view].tabs[0]};if(i>=0&&list[i])list[i]=rec;else list.unshift(rec);mpDrafts[view]=list;mpSave();closeModal();notice('Taslak yalnızca tarayıcıya kaydedildi.')}
function mpRemove(i){if(!confirm('Bu yerel taslağı silmek istiyor musun?'))return;mpRecords().splice(i,1);mpSave();render();notice('Yerel taslak silindi.')}
function mpPreview(i){let fields=mpFields(),v=mpRecords()[i]?.values||[];showModal(`<div class="modal-head"><h3>Kayıt Önizlemesi</h3><button class="modal-close" onclick="closeModal()">×</button></div><div class="mp-modal-note">Örnek kayıt; PDF, GİB, kargo etiketi veya platform onayı değildir.</div><div class="mp-summary">${fields.map((f,j)=>`<div><span>${esc(f.split('|')[0])}</span><strong>${esc(v[j]||'—')}</strong></div>`).join('')}</div><div class="modal-foot"><button class="btn" onclick="closeModal()">Kapat</button><button class="btn btn-primary" onclick="closeModal();mpForm(${i})">Düzenle</button></div>`)}
function mpCSV(){const fields=mpFields().map(f=>f.split('|')[0]);const rows=[fields,...mpRecords().map(r=>r.values)];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(';')).join('\r\n');let a=document.createElement('a'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download=`${view}-tarayici-taslaklari.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function mpChecklist(){let p=operationalPages[view],tab=workspaceTab[view]||p.tabs[0],tips=MP_TIPS[view]||['Kayıt ve alan doğrulaması','Kanal / iş kuralı kontrolü','Önizleme ve kullanıcı onayı','İşlem geçmişi kaydı','Dış API entegrasyonu (sonraki aşama)'];return `<section class="card mp-steps"><div class="mp-block-title">${ic('layers',18)} İş akışı ve kontrol adımları</div>${tips.map((t,i)=>`<div class="mp-step"><div class="mp-step-index">${String(i+1).padStart(2,'0')}</div><span>${esc(t)}</span></div>`).join('')}<div class="mp-warning">${ic('shield',15)} <span><b>${esc(tab)}</b> için canlı veri gönderimi henüz etkin değildir.</span></div></section>`}
function operatingPage(){const p=operationalPages[view],active=workspaceTab[view]||p.tabs[0],find=workspaceSearch.toLocaleLowerCase('tr-TR'),rows=p.rows.filter(r=>(!find||r.join(' ').toLocaleLowerCase('tr-TR').includes(find))&&(workspaceStatus==='Tümü'||r[r.length-1]===workspaceStatus)),drafts=mpRecords().map((r,i)=>({...r,index:i})).filter(r=>r.tab===active||!r.tab);return head(p.title,p.sub,btn(ic('plus',15)+' Yeni taslak','mpForm()','btn-primary')+btn(ic('download',15)+' CSV','mpCSV()',''))+`<div class="mp-hero"><div><span class="mp-kicker">İNTERNET TEKSTİL / DETAYLI OPERASYON PANELİ</span><h2>${esc(active)}</h2><p>${esc(p.sub)} Her alt işlem için ayrı taslak formu ve kontrol adımları bulunur.</p><div class="mp-hero-chips"><span>${ic('shield',13)} Frontend demo</span><span>${ic('check',13)} Yerel taslak kaydı</span><span>${ic('grid',13)} ${p.tabs.length} alt ekran</span></div></div><div class="mp-hero-number"><strong>${mpRecords().length}</strong><span>Kaydedilmiş taslak</span></div></div><section class="card mp-body"><div class="op-tab-scroll"><div class="op-tabs">${p.tabs.map(t=>`<button class="op-tab ${active===t?'active':''}" onclick="setWorkspaceTab('${esc(t).replaceAll("'","\\'")}')">${esc(t)}</button>`).join('')}</div></div><div class="mp-sectionbar"><div><strong>${esc(active)} işlemleri</strong><small>Alanlara özel kayıt hazırlama, filtreleme ve ayrıntı görüntüleme</small></div><button class="btn btn-primary" onclick="mpForm()">${ic('plus',15)} Yeni kayıt</button></div><div class="mp-content-grid"><div class="mp-left"><div class="mp-sub-title">${ic('file',16)} Tarayıcıya kaydedilen taslaklar <span>${drafts.length}</span></div>${drafts.length?`<div class="mp-draft-list">${drafts.map(r=>`<div class="mp-draft"><div class="mp-draft-icon">${ic('file',18)}</div><div class="mp-draft-main"><strong>${esc(r.values.find(v=>v)||'Yeni taslak')}</strong><small>${esc(r.values.slice(1,4).filter(Boolean).join(' · ')||active)}</small><span>${esc(new Date(r.created).toLocaleString('tr-TR'))} · Yerel taslak</span></div><div class="mp-draft-actions"><button onclick="mpPreview(${r.index})">İncele</button><button onclick="mpForm(${r.index})">Düzenle</button><button class="mp-danger" onclick="mpRemove(${r.index})" aria-label="Sil">${ic('close',15)}</button></div></div>`).join('')}</div>`:`<div class="mp-empty">${ic('file',28)}<strong>Henüz ${esc(active.toLocaleLowerCase('tr-TR'))} taslağı bulunmuyor</strong><p>Yeni kayıt oluştur butonuyla ayrıntılı alanları doldurup arayüz akışını test edebilirsin.</p><button class="btn btn-primary" onclick="mpForm()">Taslak oluştur</button></div>`}<div class="mp-sub-title mp-example-title">${ic('grid',16)} Örnek işlem kayıtları <span>${rows.length}</span></div><div class="op-toolbar"><div class="op-tools"><input aria-label="Örnek kayıtlarda ara" placeholder="Kayıtlarda ara..." value="${esc(workspaceSearch)}" oninput="setWorkspaceSearch(this.value)"/><select aria-label="Durum filtresi" onchange="setWorkspaceStatus(this.value)"><option>Tümü</option>${[...new Set(p.rows.map(r=>r.at(-1)))].map(x=>`<option ${workspaceStatus===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="table-wrap"><table class="data-table op-table"><thead><tr>${p.cols.map(c=>`<th>${esc(c)}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr>${r.map((v,j)=>`<td>${j===0?`<strong>${esc(v)}</strong>`:j===r.length-1?`<span class="op-pill">${esc(v)}</span>`:esc(v)}</td>`).join('')}<td><button class="op-detail" onclick="showOperationalDetail(${i})">Detay →</button></td></tr>`).join('')||`<tr><td colspan="${p.cols.length+1}" class="empty-op">Filtreye uygun kayıt yok.</td></tr>`}</tbody></table></div></div><div class="mp-right">${mpChecklist()}<section class="card mp-steps"><div class="mp-block-title">${ic('shield',18)} Bu sayfadaki işlemler</div><p>Arama, filtre, örnek kayıt inceleme, detaylı form, taslak düzenleme ve CSV dışa aktarma çalışır.</p><p>Canlı entegrasyon, onaylama, barkod tahsisi, fatura kesme ve kargo gönderimi bu sürümde kapalıdır.</p><button class="btn" onclick="nav('connections')">Satış kanallarına git ${ic('arrow',14)}</button></section></div></div></section>`}
function setWorkspaceTab(t){workspaceTab[view]=t;workspaceSearch='';workspaceStatus='Tümü';render()}
function setWorkspaceSearch(s){workspaceSearch=s;const el=document.activeElement;render();const input=document.querySelector('.op-tools input');if(input){input.focus();input.setSelectionRange(s.length,s.length)}}
function setWorkspaceStatus(s){workspaceStatus=s;render()}
function exportOperational(){const p=operationalPages[view],text='\ufeff'+[p.cols.join(';'),...p.rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';'))].join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=view+'-ornek-kayitlar.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function showOperationalDetail(index=0){const p=operationalPages[view],r=p.rows[index]||p.rows[0]||[];showModal(`<div class="modal-head"><h3>${esc(p.title)} / İşlem Detayı</h3><button class="modal-close" onclick="closeModal()">×</button></div><div class="op-detail-modal"><p class="op-modal-warning">ÖNİZLEME — Bu ekran canlı veritabanına yazmaz ve dış API çağrısı yapmaz.</p><div class="op-detail-grid">${p.cols.map((c,i)=>`<div><small>${esc(c)}</small><strong>${esc(r[i]||'—')}</strong></div>`).join('')}</div><h4>İşlem alt adımları</h4>${p.tabs.map(t=>`<div class="op-detail-step">${ic('check',15)} ${esc(t)} <span>Tasarım hazır</span></div>`).join('')}<button class="btn btn-primary" onclick="closeModal()">Kapat</button></div>`)}

function render(){const previousSidebar=document.querySelector('.sidebar'),sidebarScrollTop=previousSidebar?.scrollTop||0;let content=view==='dashboard'?dashboard():view==='products'||view==='orders'?listing(view):view==='connections'?connections():view==='inventory'?inventory():view==='barcodes'?barcodes():view==='shipping'?shipping():view==='reports'?reports():view==='activity'?activities():view==='sync'?syncPage():view==='settings'?settings():operationalPages[view]?operatingPage():placeholder();app.innerHTML=frame((['trendyol','hepsiburada','n11','amazon'].includes(view)?integrationPanel(view):'')+content);const nextSidebar=document.querySelector('.sidebar');if(nextSidebar)nextSidebar.scrollTop=sidebarScrollTop}
function showModal(content){modal=`<div class="modal-layer" onclick="if(event.target===this)closeModal()"><div class="modal">${content}</div></div>`;render()}function closeModal(){modal=null;render()}
function openProduct(){showModal(`<div class="modal-head"><h3>Yeni Ürün Ekle</h3><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="addProduct(event)"><div class="form-row"><label>Ürün adı</label><input name="name" required placeholder="Örn. Bluetooth Kulaklık"/></div><div class="form-row"><label>SKU / Stok kodu</label><input name="sku" required placeholder="Örn. ELK-1100"/></div><div class="form-row"><label>Kategori</label><input name="category" value="Elektronik"/></div><div class="settings-layout"><div class="form-row"><label>Fiyat (₺)</label><input type="number" step="0.01" min="0" name="price" required/></div><div class="form-row"><label>Stok</label><input type="number" min="0" name="stock" required/></div></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Vazgeç</button><button class="btn btn-primary">${ic('plus',14)} Ürünü Ekle</button></div></form>`)}
function openEdit(id){const p=data.products.find(x=>x.id===id);if(!p)return;showModal(`<div class="modal-head"><h3>Ürünü Düzenle</h3><button class="modal-close" onclick="closeModal()">×</button></div><div class="product-cell" style="margin-bottom:23px"><span class="product-thumb">${esc(p.image)}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></span></div><form onsubmit="saveProduct(event,'${p.id}')"><div class="form-row"><label>Satış Fiyatı (₺)</label><input type="number" name="price" min="0" step="0.01" value="${p.price}" required/></div><div class="form-row"><label>Stok Miktarı</label><input type="number" name="stock" min="0" value="${p.stock}" required/></div><div class="form-row"><label>Durum</label><select name="status"><option ${p.status==='Aktif'?'selected':''}>Aktif</option><option ${p.status==='Pasif'?'selected':''}>Pasif</option></select></div><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Vazgeç</button><button class="btn btn-primary">Değişiklikleri Kaydet</button></div></form>`)}function openOrder(id){const o=data.orders.find(x=>x.id===id);if(!o)return;showModal(`<div class="modal-head"><h3>Sipariş Durumu</h3><button class="modal-close" onclick="closeModal()">×</button></div><p class="page-sub" style="margin-bottom:23px">#${esc(o.id)} · ${esc(o.customer)} · ${esc(o.channel)}</p><form onsubmit="saveOrder(event,'${o.id}')"><div class="form-row"><label>Yeni Durum</label><select name="status">${['Yeni','Hazırlanıyor','Kargolandı','Tamamlandı','İptal'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></div><p class="page-sub" style="line-height:1.6">Bu işlem sadece yerel demo siparişinin durumunu değiştirir; pazaryerine iletilmez.</p><div class="modal-foot"><button type="button" class="btn" onclick="closeModal()">Vazgeç</button><button class="btn btn-primary">Kaydet</button></div></form>`)}
async function mutate(fn,good){try{await fn();modal=null;await load();render();notice(good)}catch(e){notice('Hata: '+e.message)}}async function addProduct(e){e.preventDefault();const f=e.target;const p=Object.fromEntries(new FormData(f));await mutate(()=>api('products',{method:'POST',body:JSON.stringify({name:p.name,sku:p.sku,category:p.category,price:Number(p.price),stock:Number(p.stock),image:'📦',channels:[]})}),'Ürün eklendi ve yerel veriye kaydedildi.')}async function saveProduct(e,id){e.preventDefault();let v=Object.fromEntries(new FormData(e.target));await mutate(()=>api('products/'+id,{method:'PUT',body:JSON.stringify({price:Number(v.price),stock:Number(v.stock),status:v.status})}),'Ürün bilgileri güncellendi.')}async function saveOrder(e,id){e.preventDefault();let v=Object.fromEntries(new FormData(e.target));await mutate(()=>api('orders/'+id+'/status',{method:'PUT',body:JSON.stringify({status:v.status})}),'Sipariş durumu güncellendi.')}async function toggleConnection(id,enabled){await mutate(()=>api('connections/'+id,{method:'PUT',body:JSON.stringify({enabled})}),'Demo bağlantı durumu değiştirildi.')}async function doSync(){await mutate(()=>api('sync/demo',{method:'POST'}),'Yerel demo senkronizasyon kaydı oluşturuldu.')}async function saveSettings(e){e.preventDefault();const f=e.target;await mutate(()=>api('settings',{method:'PUT',body:JSON.stringify({businessName:f.businessName.value,currency:f.currency.value,lowStockThreshold:Number(f.lowStockThreshold.value),emailNotifications:f.emailNotifications.checked,syncNotifications:f.syncNotifications.checked})}),'Ayarlar kaydedildi.')}function exportOrders(){let rows=[['Sipariş','Müşteri','Platform','Ürün','Tutar','Adet','Durum','Tarih'],...data.orders.map(o=>[o.id,o.customer,o.channel,o.product,o.total,o.quantity,o.status,dt(o.date)])];let csv='\ufeff'+rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='siparisler.csv';a.click();URL.revokeObjectURL(a.href)}
(async()=>{try{await load();let requested=location.hash.slice(1);view=names[requested]?requested:'dashboard';render()}catch(e){app.innerHTML=`<div style="padding:75px;max-width:550px;margin:auto"><h1>Backend bağlantısı kurulamadı</h1><p>Uygulamayı HTML dosyasına çift tıklayarak değil, <code>dotnet run --urls "http://localhost:5080"</code> komutuyla başlatın.</p><pre>${esc(e.message)}</pre></div>`}})();


